  function categoryManager(){if(!canManageUsers)return;showModal(`<div class="modal-head"><div><h2>Funções e classificações</h2><p>Cadastre as classificações disponíveis para usuários e tarefas.</p></div><button class="close-button" data-close>×</button></div><div class="detail-body"><form id="category-form" class="category-form"><div class="form-field"><label for="category-name">Nova função / classificação</label><input id="category-name" maxlength="40" placeholder="Ex.: Escalas"><small class="error" data-error="category"></small></div><button class="button primary">＋ Criar</button></form><div id="category-list" class="category-list">${taskCategories.map(c=>`<div class="category-row"><strong>${esc(c.name)}</strong><small>Disponível para atribuição e classificação de tarefas</small></div>`).join('')}</div></div><div class="detail-actions"><button class="button secondary" data-close>Fechar</button></div>`);$('#category-form').addEventListener('submit',async e=>{e.preventDefault();const name=$('#category-name').value.trim();$('[data-error="category"]').textContent=name?'':'Informe um nome.';if(!name)return;try{const result=await api('/api/task-categories',{method:'POST',body:{name}});taskCategories.push(result.category);taskCategories.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));$('#category-list').innerHTML=taskCategories.map(c=>`<div class="category-row"><strong>${esc(c.name)}</strong><small>Disponível para atribuição e classificação de tarefas</small></div>`).join('');$('#category-name').value='';notify('Função/classificação criada.');}catch(error){$('[data-error="category"]').textContent=error.message;}});}
