  const adiantamentoStyles=`.adiantamento-page{font:10pt/1.17 "Times New Roman",serif}.adiantamento-header{margin-bottom:8mm}.adiantamento-header img{width:23mm!important;height:22mm!important;object-fit:contain;margin:0 auto 1mm!important}.adiantamento-header strong{font-size:10pt}.adiantamento-identification{margin:0 0 7mm;line-height:1.12}.adiantamento-opening{margin:0 0 1mm!important;text-align:left}.adiantamento-page .req-to{margin:0 0 1mm}.adiantamento-page .req-object{margin:0 0 13mm}.adiantamento-body{text-align:justify;text-indent:25mm;margin:0 0 4mm!important}.adiantamento-requester-signature{text-align:center;margin:13mm 0 10mm}.adiantamento-dispatch{margin-top:0}.adiantamento-dispatch h2{font-size:11pt;margin:0 0 5mm}.adiantamento-dispatch p{margin:1.5mm 0;text-align:justify}.adiantamento-hand-date{text-align:center;margin:6mm 0 0!important}.adiantamento-signature{text-align:center;display:flex;flex-direction:column;gap:1mm;margin:auto 0 4mm;padding-top:15mm}.adiantamento-signature span{font-size:10pt}.adiantamento-page{break-after:auto;page-break-after:auto}@media print{.adiantamento-page{min-height:271mm!important;height:271mm;overflow:hidden;break-after:auto;page-break-after:auto}}`;
  function openDocument(id){const d=documents.find(x=>x.id===Number(id));if(!d)return;const canEditThisDocument=isRequirementKind(d.kind)?canEditRequirements:canEditDocuments;let markup;try{markup=renderDocumentMarkup(d);}catch(error){console.error('Falha ao montar prévia do documento:',error);notify('Não foi possível abrir a prévia deste documento. Verifique os dados salvos e tente novamente.');return;}const docTitle=d.kind==='fatd'?'FATD · PROCESSO':d.kind==='prorrogacao'?'REQUERIMENTO · INFORMAÇÃO Nº':d.kind==='adiantamento13'?'REQUERIMENTO · ADIANTAMENTO DE 13º':'DOCUMENTO · BOLETIM NR';showModal(`<style>${printStyles}${printTitleOverrides}${prorrogacaoStyles}${adiantamentoStyles}</style><div class="modal-head"><div><p class="eyebrow">${docTitle} ${esc(d.bulletin_number)}</p><h2>Documento arquivado</h2></div><button class="close-button" data-close>×</button></div><div class="document-preview-wrap">${markup}</div><div class="detail-actions"><button class="button secondary" data-close>Fechar</button><button class="button secondary" data-doc-print="${d.id}">Imprimir / PDF</button>${canEditThisDocument?`<button class="button primary" data-doc-edit="${d.id}">Editar</button><button class="button delete-button" data-delete-kind="document" data-delete-id="${d.id}">Excluir</button>`:''}</div>`,true);}
  function longDate(value,weekday=true){if(!value)return '________________';const d=new Date(`${value}T12:00:00`),dateText=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric'}).format(d);return weekday?`${dateText} (${new Intl.DateTimeFormat('pt-BR',{weekday:'long'}).format(d)})`:dateText;}
  const cellText=v=>esc(v||'').replace(/\n/g,'<br>');
  function aditamentoMarkup(doc){const d=doc.data||{},days=normalizeAditDays(d),notices=d.notices||{},parts=[['instruction','2ª PARTE – INSTRUÇÃO'],['general','3ª PARTE – ASSUNTOS GERAIS E ADMINISTRATIVOS'],['discipline','4ª PARTE – JUSTIÇA E DISCIPLINA']],dayMarkup=days.map((day,index)=>{const rows=day.groups.flatMap(g=>{const groupRows=(g.rows||[]).filter(r=>r.service||r.personnel);return groupRows.map(r=>`<tr><td>${cellText(r.service)}</td><td>${cellText([r.rank,r.personnel].filter(Boolean).join(' '))}</td></tr>`)});return `<section class="adit-day-print ${index?'adit-day-continuation':''}"><h3 class="adit-day-title">Para o dia ${esc(longDate(day.date))}</h3><table class="adit-scale"><colgroup><col style="width:35%"><col style="width:65%"></colgroup><thead><tr><th>Serviço</th><th>Militar(es)</th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="2">Escala não informada.</td></tr>'}<tr><td><b>Parada Diária</b></td><td><b>Horário:</b> ${cellText(d.paradeTime)}<br><b>Local:</b> ${cellText(d.paradeLocation)}</td></tr></tbody></table></section>`;}).join(''),partMarkup=parts.map(([key,title])=>{const items=(notices[key]||[]).filter(n=>n.title||n.body);return `<section class="adit-part"><h3>${title}</h3>${items.length?items.map(n=>`<div class="adit-notice-print"><strong>${cellText(n.title)}</strong>${n.body?`<p>${cellText(n.body)}</p>`:''}</div>`).join(''):'<p class="adit-no-change">Sem Alteração</p>'}</section>`;}).join(''),signerRole=d.mainResponding?'Resp. Sargenteante da 3ª Bateria de Obuses':'Sargenteante da 3ª Bateria de Obuses',commanderRole=d.commanderResponding?'Resp. Comandante da 3ª Bateria de Obuses':'Comandante da 3ª Bateria de Obuses';return `<article class="paper paper-aditamento"><div class="paper-header"><strong>MINISTÉRIO DA DEFESA</strong><strong>EXÉRCITO BRASILEIRO</strong><strong>25º GRUPO DE ARTILHARIA DE CAMPANHA</strong><strong>(C Art Cav/1831)</strong><strong>GRUPO LEITE DE CASTRO</strong><strong>3ª BATERIA DE OBUSES</strong></div><h2 class="paper-title">ADITAMENTO AO BOLETIM INTERNO Nr ${esc(doc.bulletin_number)} DE ${esc(longDate(d.bulletinDate||doc.document_date,false).toUpperCase())}</h2><p class="paper-intro">PARA CONHECIMENTO DESTA BATERIA E DEVIDA EXECUÇÃO PUBLICO O SEGUINTE:</p><h3 class="adit-part-title">1ª PARTE – SERVIÇOS DIÁRIOS</h3>${dayMarkup}${partMarkup}<div class="paper-signature adit-signature"><strong>${cellText(d.mainSigner)}</strong><span>${signerRole}</span></div><div class="paper-signature adit-signature adit-commander-signature"><strong>${cellText(d.commander)}</strong><span>${commanderRole}</span></div></article>`;}
  function renderDocumentMarkup(doc){if(doc.kind==='prorrogacao')return prorrogacaoMarkup(doc);if(doc.kind==='adiantamento13')return adiantamentoMarkup(doc);if(doc.kind==='pernoite')return pernoiteMarkup(doc);if(doc.kind==='aditamento')return aditamentoMarkup(doc);const d=doc.data||{},header=`<div class="paper-header"><strong>MINISTÉRIO DA DEFESA</strong><strong>EXÉRCITO BRASILEIRO</strong><strong>${cellText(d.unit||'25º GRUPO DE ARTILHARIA DE CAMPANHA')}</strong><span>(Organização Militar)</span><strong>GRUPO LEITE DE CASTRO</strong><strong>${cellText(d.subunit||'3ª BATERIA DE OBUSES')}</strong></div>`;
    if(doc.kind==='fatd'){const authority=[d.authorityRank,d.authorityName].filter(Boolean).join(' '),military=[d.militaryName,d.militaryRank].filter(Boolean).join(' - '),participant=[d.participantName,d.participantRank].filter(Boolean).join(' — '),blankLines=count=>Array.from({length:count},()=>'<div class="fatd-writing-line"></div>').join(''),fatdDate=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${d.date||doc.document_date}T12:00:00`)).replace(/\sde\s/g,' ').replace(/\./g,'').toUpperCase();return `<div class="fatd-document"><article class="paper fatd-page fatd-page-one"><div class="fatd-emblem"><img src="${location.origin}/assets/documents/fatd-emblem.png" alt="Símbolo Nacional presente no modelo fornecido"></div><div class="fatd-heading"><strong>MINISTÉRIO DA DEFESA</strong><strong>EXÉRCITO BRASILEIRO</strong><strong>25º GRUPO DE ARTILHARIA DE CAMPANHA</strong><strong>(Corpo de Artilharia a Cavalo/1831)</strong><strong>GRUPO LEITE DE CASTRO</strong></div><h2 class="fatd-title">FORMULÁRIO DE APURAÇÃO DE TRANSGRESSÃO DISCIPLINAR</h2><div class="fatd-process-row"><span><b>PROCESSO Nº:</b> ${cellText(doc.bulletin_number)}</span><span><b>DATA:</b> ${esc(fatdDate)}</span></div><section class="fatd-section fatd-identification"><h3>IDENTIFICAÇÃO DO MILITAR</h3><div><b>Grau Hierárquico:</b> ${cellText(d.militaryRank)} <b class="fatd-right-label">IDT/CPF:</b> ${cellText(d.militaryId)}</div><div><b>Nome Completo:</b> ${cellText(d.militaryName)}</div><div><b>Subunidade/OM:</b> ${cellText(d.militarySubunit)}</div></section><section class="fatd-section fatd-identification"><h3>IDENTIFICAÇÃO DO PARTICIPANTE</h3><div><b>Grau Hierárquico:</b> ${cellText(d.participantRank)} <b class="fatd-right-label">NR/IDT:</b> ${cellText(d.participantId)}</div><div><b>Nome Completo:</b> ${cellText(d.participantName)}</div><div><b>Subunidade/OM:</b> ${cellText(d.participantSubunit)}</div></section><section class="fatd-section fatd-report"><h3>RELATO DO FATO</h3><p>${cellText(d.report)}</p><div class="fatd-participant-sign">${cellText(participant)}</div></section><section class="fatd-section fatd-awareness"><h3>CIENTE DO MILITAR ARROLADO</h3><p>Declaro que tenho conhecimento de que me está sendo imputada a autoria do fato acima e me foi concedido o prazo de três dias úteis, para apresentar, por escrito, as minhas justificativas ou razões de defesa.</p><div class="fatd-date-printed"><b>Data:</b> &nbsp; ____ &nbsp; de &nbsp; ______________ &nbsp; de ${esc((d.date||doc.document_date||'').slice(0,4))}</div><div class="fatd-military-sign">${cellText(military)}</div></section></article><article class="paper fatd-page fatd-page-two"><section class="fatd-defense"><h3>JUSTIFICATIVAS / RAZÕES DE DEFESA</h3><div class="fatd-lines">${blankLines(13)}</div><p class="fatd-hand-date">DATA: &nbsp;____ / ____ / ______</p><div class="fatd-military-sign">${cellText(military)}</div></section><section class="fatd-decision"><h3>DECISÃO DA AUTORIDADE COMPETENTE PARA APLICAR A PUNIÇÃO DISCIPLINAR.</h3><div class="fatd-lines">${blankLines(8)}</div><p class="fatd-hand-date">DATA: ____ / ____ / ______</p><div class="fatd-authority-sign"><strong>${cellText(authority)}</strong>${d.authorityRole?`<span>${cellText(d.authorityRole)}</span>`:''}${d.authoritySubunit?`<span>${cellText(d.authoritySubunit)}</span>`:''}</div><p class="fatd-publication">PUNIÇÃO PUBLICADA NO BI nº ________, de ______ de __________________ de __________.</p></section></article></div>`;}
    const rowHtml=(r)=>`<tr><th>${cellText(r.rank)}</th><td>${r.description?`<b>${cellText(r.description)}:</b> `:''}${cellText(r.personnel)}</td><td>${Number(r.count)||0}</td></tr>`,sum=rows=>(rows||[]).reduce((n,r)=>n+(Number(r.count)||0),0),inTotal=sum(d.formation),outTotal=sum(d.destinations),grand=inTotal+outTotal;
    return `<article class="paper paper-pernoite"><div class="pernoite-top"><aside><i>VISTO:</i><div class="signature-line">${cellText(d.commander)}</div><small>${cellText(d.commanderRole)}</small></aside>${header}</div><div class="pernoite-unit">${cellText(d.subunit||'3ª BATERIA DE OBUSES')}</div><h2 class="pernoite-title">REVISTA DO RECOLHER DO DIA ${esc(longDate(d.serviceDate))}</h2><p class="paper-center bulletin-ref">Boletim Interno Nr ${esc(doc.bulletin_number)} · ${esc(longDate(d.bulletinDate,false))}</p><table class="pernoite-table"><thead><tr><th>GRADUAÇÃO</th><th>EM FORMA</th><th>SOMA</th></tr></thead><tbody>${(d.formation||[]).map(rowHtml).join('')}<tr class="total-row"><th colspan="2">TOTAL</th><td>${inTotal}</td></tr></tbody></table><table class="pernoite-table destinations"><thead><tr><th>GRADUAÇÃO</th><th>OUTROS DESTINOS</th><th>SOMA</th></tr></thead><tbody>${(d.destinations||[]).map(rowHtml).join('')}<tr class="total-row"><th colspan="2">TOTAL</th><td>${outTotal}</td></tr><tr class="state-row"><th colspan="2">ESTADO DO EFETIVO</th><td>${grand}</td></tr></tbody></table><p class="paper-center location-date">${cellText(d.city)}, ${esc(longDate(d.serviceDate,false))}.</p><div class="paper-signature"><strong>${cellText(d.mainSigner)}</strong><span>${cellText(d.mainRole)}</span></div><table class="review-box"><tbody><tr><th colspan="2">REVISTA DO RECOLHER ______ ALTERAÇÃO</th></tr><tr><td class="review-stamp">Visto:</td><td>Quartel em ${cellText(d.city)}, ____ de ______________ de ______.</td></tr><tr><td class="review-stamp">OF DE DIA</td><td>${cellText(d.officerOfDay)}<br><br>______________________________ &nbsp; Sgt de Dia: ${cellText(d.sergeantOfDay)}</td></tr><tr><td class="review-stamp">OBSERVAÇÕES</td><td>${cellText(d.observations)}</td></tr></tbody></table></article>`;
  }
  async function deleteRecord(kind,id){const labels={document:'documento','force-map':'Mapa da Força',scale:'escala de serviço',vacation:'período de férias','unit-person':'cadastro do efetivo',user:'usuário',task:'tarefa'},label=labels[kind];if(!label)return;let message=`Excluir este ${label}? Esta ação não pode ser desfeita.`;if(kind==='unit-person')message='Excluir esta ficha do efetivo? Os períodos de férias associados e a participação desta pessoa nas escalas também serão removidos.';if(kind==='user'&&systemUsers.find(x=>x.id===Number(id))?.display_name===user)message='Esse usuário está conectado e não pode ser excluído.';if(kind==='user'&&systemUsers.find(x=>x.id===Number(id))?.display_name===user){notify(message);return;}if(!window.confirm(message))return;try{if(kind==='task'){await api(`/api/tasks/${id}`,{method:'DELETE'});data.tasks=data.tasks.filter(t=>t.id!==String(id));save();render();renderInbox();closeModal();notify('Tarefa excluída.');return;}const paths={document:`/api/documents/${id}`,'force-map':`/api/force-maps/${id}`,scale:`/api/service-scales/${id}`,vacation:`/api/vacation-plan/${id}`,'unit-person':`/api/unit-personnel/${id}`,user:`/api/users/${id}`};await api(paths[kind],{method:'DELETE'});if(kind==='document'){documents=documents.filter(x=>x.id!==Number(id));renderDocuments();}else if(kind==='force-map'){forceMaps=forceMaps.filter(x=>x.id!==Number(id));renderForceMaps();}else if(kind==='scale'){serviceScales=serviceScales.filter(x=>x.id!==Number(id));if(selectedScale?.id===Number(id)){selectedScale=null;$('#scale-board').classList.add('hidden');}renderScaleList();}else if(kind==='vacation'){vacationPeriods=vacationPeriods.filter(x=>x.id!==Number(id));renderVacation();await loadNotices();render();}else if(kind==='unit-person'){unitPersonnel=unitPersonnel.filter(x=>x.id!==Number(id));vacationPeriods=vacationPeriods.filter(x=>x.person_id!==Number(id));serviceScales=serviceScales.map(s=>({...s,participants:s.participants.filter(p=>p.id!==Number(id)),assignments:Object.fromEntries(Object.entries(s.assignments).filter(([key])=>Number(key.split('|')[0])!==Number(id)))}));if(selectedScale){selectedScale=serviceScales.find(s=>s.id===selectedScale.id)||null;if(selectedScale)renderScaleBoard();}renderUnitRoster();await loadNotices();render();}else if(kind==='user'){systemUsers=systemUsers.filter(x=>x.id!==Number(id));renderPersonnel();}closeModal();notify(`${label.charAt(0).toUpperCase()+label.slice(1)} excluído.`);}catch(error){notify(error.message||`Não foi possível excluir ${label}.`);}}
  function printDocument(id){const doc=documents.find(x=>x.id===Number(id));if(!doc)return;let markup;try{markup=renderDocumentMarkup(doc);}catch(error){console.error('Falha ao montar documento para impressão:',error);notify('Não foi possível preparar a impressão deste documento. Verifique os dados salvos e tente novamente.');return;}const old=document.querySelector('#sigase-print-host');if(old)old.remove();const host=document.createElement('main');host.id='sigase-print-host';host.innerHTML=`<style>${printStyles}${printTitleOverrides}${isRequirementKind(doc.kind)?prorrogacaoStyles:''}${doc.kind==='adiantamento13'?adiantamentoStyles:''}@media screen{#sigase-print-host{display:none!important}}@media print{html,body{width:auto!important;height:auto!important;overflow:visible!important;background:#fff!important;margin:0!important;padding:0!important}body>*:not(#sigase-print-host){display:none!important}#sigase-print-host{display:block!important;position:static!important;visibility:visible!important;opacity:1!important;width:auto!important;height:auto!important;overflow:visible!important;background:#fff!important;color:#111!important;padding:0!important;margin:0!important}}</style>${markup}`;document.body.appendChild(host);const cleanup=()=>{host.remove();window.removeEventListener('afterprint',cleanup);};window.addEventListener('afterprint',cleanup,{once:true});try{window.focus();window.print();setTimeout(cleanup,120000);}catch(error){cleanup();console.error('Falha ao iniciar impressão:',error);notify('Não foi possível abrir a impressão. Tente novamente.');}}
  async function loadScales(){try{const result=await api('/api/service-scales');serviceScales=result.scales;renderScaleList();if(selectedScale){selectedScale=serviceScales.find(s=>s.id===selectedScale.id)||null;if(selectedScale)renderScaleBoard();else $('#scale-board').classList.add('hidden');}}catch(error){$('#scale-list').innerHTML=empty('Escalas indisponíveis',esc(error.message));}}
  function renderScaleList(){const list=$('#scale-list');list.innerHTML=serviceScales.length?serviceScales.map(s=>`<div class="scale-list-item"><button class="scale-list-card ${selectedScale?.id===s.id?'active':''}" data-scale-open="${s.id}"><span class="scale-list-icon">▥</span><span class="scale-list-text"><strong>${esc(s.name)}</strong><small>${scaleModeName(s.mode)} · ${s.participants.length} militares · ${s.services.length} serviços</small></span><span class="scale-list-arrow">›</span></button>${canEditScales?`<button class="button delete-button" data-delete-kind="scale" data-delete-id="${s.id}">Excluir</button>`:''}</div>`).join(''):empty('Nenhuma escala criada','Crie uma escala para começar.');}
  const scaleModeName=mode=>mode==='corrida'?'Escala corrida':mode==='preta_vermelha'?'Preta e vermelha':'Completa · preta, vermelha e roxa';
  function openScale(id){selectedScale=serviceScales.find(s=>s.id===Number(id))||null;if(!selectedScale)return;scaleMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderScaleList();renderScaleBoard();}
  function dayISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function scaleDayClass(day){if(selectedScale.mode==='corrida')return 'day-black';const date=dayISO(day);if(selectedScale.red_dates.includes(date)||day.getDay()===0||day.getDay()===6)return 'day-red';if(selectedScale.mode==='completa'&&day.getDay()===5)return 'day-purple';return 'day-black';}
