  function scaleAssignmentInfo(value){if(typeof value!=='string')return {service:'',excluded:false,reason:'',swapName:'',restCount:null};if(value.startsWith('__FORA_ESCALA__::'))return {service:'',excluded:true,reason:value.slice('__FORA_ESCALA__::'.length),swapName:'',restCount:null};if(value.startsWith('__FOLGA_MANUAL__::')){const count=Number(value.slice('__FOLGA_MANUAL__::'.length));return {service:'',excluded:false,reason:'',swapName:'',restCount:Number.isInteger(count)?Math.max(0,Math.min(99,count)):null};}if(value.startsWith('__TROCA_SERVICO__::')){try{const parsed=JSON.parse(value.slice('__TROCA_SERVICO__::'.length));return {service:parsed.service||'',excluded:false,reason:'',swapName:parsed.swap_name||'',restCount:null};}catch{return {service:'',excluded:false,reason:'',swapName:'',restCount:null};}}return {service:value,excluded:false,reason:'',swapName:'',restCount:null};}
