  async function changeStatus(id,status){const t=data.tasks.find(x=>x.id===id);if(!canEditTasks||!t)return;try{await api(`/api/tasks/${id}`,{method:'PUT',body:{status}});await loadTasks();closeModal();render();renderInbox();notify(status==='Concluída'?'Tarefa concluída para todos os responsáveis.':'Tarefa marcada como em andamento.');}catch(error){notify(error.message||'Não foi possível atualizar a tarefa.');}}
