  function pernoiteMarkup(doc){const d=doc.data||{},formation=pernoiteGroups(d,'formation'),destinations=pernoiteGroups(d,'destinations'),groupSum=g=>(g.services||[]).reduce((n,r)=>n+(Number(r.count)||0),0),total=groups=>groups.reduce((n,g)=>n+groupSum(g),0),inTotal=total(formation),outTotal=total(destinations),grand=inTotal+outTotal,entries=g=>(g.services||[]).filter(r=>r.description||r.personnel||r.rankLabel).map(r=>{const label=g.rank==='DISPENSA MÉDICA'?r.rankLabel:r.description;return `<div class="pernoite-entry">${label?`<b>${cellText(label)}:</b> `:''}${cellText(r.personnel)}</div>`;}).join('')||'<span class="pernoite-dash">-</span>',rows=groups=>groups.map(g=>`<tr><th>${cellText(g.rank)}</th><td>${entries(g)}</td><td class="pernoite-sum">${groupSum(g)||'-'}</td></tr>`).join(''),commanderRole=d.commanderActing?'Resp. Cmt 3ª BO':'Cmt da 3ª BO',signerRole=d.mainResponding?'Resp. Sargenteante da 3ªBia O':'Sargenteante da 3ª Bateria de Obuses';return `<article class="paper paper-pernoite"><div class="pernoite-top"><aside class="pernoite-commander"><i>VISTO:</i><div class="signature-line"></div><strong>${cellText(d.commander)}</strong><small>${commanderRole}</small></aside><div class="paper-header"><strong>MINISTÉRIO DA DEFESA</strong><strong>EXÉRCITO BRASILEIRO</strong><strong>25º GRUPO DE ARTILHARIA DE CAMPANHA</strong><strong>(Corpo de Artilharia a Cavalo/1831)</strong><strong>GRUPO LEITE DE CASTRO</strong><strong>3ª BATERIA DE OBUSES</strong></div></div><div class="pernoite-unit">3ª BATERIA DE OBUSES</div><h2 class="pernoite-title">REVISTA DO RECOLHER DO DIA ${esc(longDate(d.serviceDate))}</h2><table class="pernoite-table"><thead><tr><th>GRADUAÇÃO</th><th>EM FORMA</th><th>SOMA</th></tr></thead><tbody>${rows(formation)}<tr class="total-row"><th colspan="2">TOTAL</th><td>${inTotal||'-'}</td></tr></tbody></table><table class="pernoite-table destinations"><thead><tr><th>GRADUAÇÃO</th><th>OUTROS DESTINOS</th><th>SOMA</th></tr></thead><tbody>${rows(destinations)}<tr class="total-row"><th colspan="2">TOTAL</th><td>${outTotal||'-'}</td></tr><tr class="state-row"><th colspan="2">ESTADO DO EFETIVO</th><td>${grand||'-'}</td></tr></tbody></table><p class="paper-center location-date">${cellText(d.city||'Bagé-RS')}, ${esc(longDate(d.signatureDate||d.serviceDate,false))}.</p><div class="paper-signature pernoite-main-signature"><strong>${cellText(d.mainSigner)}</strong><span>${signerRole}</span></div><table class="review-box pernoite-review"><tbody><tr><th colspan="2">REVISTA DO RECOLHER ______ ALTERAÇÃO</th></tr><tr><td class="review-stamp review-officer" rowspan="2"><span>Visto:</span><span class="review-signature-line"></span><b>OF DE DIA</b></td><td>Quartel em ${cellText(d.city||'Bagé-RS')}, ____ de ______________ de ____.</td></tr><tr><td class="review-sergeant"><span class="review-signature-line"></span><span>Sgt de Dia - ${cellText(d.sergeantOfDay||'')}</span></td></tr><tr><td class="review-stamp">OBS: Havendo alterações, deverão ser lançadas ao lado.</td><td class="review-observations">${Array.from({length:3},()=>'<div></div>').join('')}</td></tr></tbody></table></article>`;}
